package cn.zhuatech.finagent.controller;
import cn.zhuatech.finagent.agent.AgentRuntime; import cn.zhuatech.finagent.common.ApiResponse; import cn.zhuatech.finagent.dto.FinAgentDto.*; import cn.zhuatech.finagent.service.FinAgentService; import cn.zhuatech.finagent.service.FinancialControlService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final FinAgentService service;private final AgentRuntime runtime;private final FinancialControlService control;public WorkspaceController(FinAgentService service,AgentRuntime runtime,FinancialControlService control){this.service=service;this.runtime=runtime;this.control=control;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}@PostMapping("/agent-preview") public ApiResponse<AgentRuntime.AgentResult> preview(@RequestBody Map<String,String> body){return ApiResponse.ok(runtime.run(new AgentRuntime.AgentRequest(body.getOrDefault("objective","执行月结检查"),Map.of("mode","demo"))));}@PostMapping("/financial-control") public ApiResponse<FinancialControlService.ControlResult> evaluate(@Valid @RequestBody FinancialControlService.ControlRequest request){return ApiResponse.ok("财务控制评估完成",control.evaluate(request));}}
